export const LAB_NETWORK_KEY='mogusbio:lab-network:v1';
export function laboratoryNetwork({storage,hash=''}={}){if(hash==='#simulation')return'simulation';if(hash==='#devnet')return'devnet';try{return storage?.getItem(LAB_NETWORK_KEY)==='simulation'?'simulation':'devnet';}catch{return'devnet';}}
export function mountLabNetwork(document,{storage,window=document.defaultView??globalThis.window,onChange=()=>{}}={}){const mode=laboratoryNetwork({storage,hash:window?.location?.hash}),select=document.getElementById('lab-network'),label=document.getElementById('lab-network-label');if(label)label.textContent=mode==='devnet'?'Devnet · test tokens':'Local simulation';for(const [id,text]of [['lab-ops-network',mode==='devnet'?'MOGUSBIO / SOLANA DEVNET':'MOGUSBIO / LOCAL SIMULATION'],['lab-mode-note',mode==='devnet'?'SOLANA DEVNET / TEST TOKENS':'LOCAL SIMULATION / NO REAL FUNDS'],['lab-funds-note',mode==='devnet'?'DEVNET TEST TOKENS · NO MAINNET FUNDS':'SIMULATED ASSETS · NO REAL FUNDS']]){const node=document.getElementById(id);if(node)node.textContent=text;}document.getElementById('lab-account-stats')?.setAttribute?.('aria-label',mode==='devnet'?'Devnet wallet balances':'Simulation balances');if(!select)return{mode,close(){}};select.value=mode;const change=()=>{const value=select.value;if(!['devnet','simulation'].includes(value))return;try{storage?.setItem(LAB_NETWORK_KEY,value);}catch{}onChange(value);if(window?.location){window.location.hash=value==='simulation'?'simulation':'devnet';window.location.reload?.();}};select.addEventListener('change',change);return{mode,close(){select.removeEventListener?.('change',change);}};}
